#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-10-11

# ============================================================================
# pre-commit plugins-src-guard: a src/ path DELETED earlier on the branch must
# not excuse a staged plugins/ edit (CodeRabbit #4710).
# ============================================================================
# The hook builds PLUGINS_SRC_GUARD_BRANCH_FILES with
# `git diff --name-only <merge-base> HEAD`. Without --diff-filter=d that list
# still names deleted paths, so a src/skills/<s>/<f> removed in an earlier
# branch commit covered a staged plugins/ork/skills/<s>/<f> edit: the guard
# allowed a plugins/ file whose src/ counterpart no longer exists anywhere.
#
# This test exercises the real installed hook in a disposable repo. The
# control case (src/ file modified earlier on the branch) keeps the #4661
# exemption alive; the deleted case must fail. Before the fix the deleted
# case printed OK; after --diff-filter=d it prints FAILED and names the
# plugins/ path.
#
# Test Count: 2
# ============================================================================

set -euo pipefail
unset GIT_DIR GIT_WORK_TREE GIT_INDEX_FILE GIT_PREFIX GIT_COMMON_DIR GIT_OBJECT_DIRECTORY

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
fixture=$(mktemp -d "${TMPDIR:-/tmp}/ork-guard-deleted-src.XXXXXX")
trap 'rm -rf "$fixture"' EXIT

RED='\033[0;31m'
GREEN='\033[0;32m'
NC='\033[0m'
TESTS_PASSED=0
TESTS_FAILED=0
log_pass() { echo -e "  ${GREEN}✓${NC} $1"; TESTS_PASSED=$((TESTS_PASSED + 1)); }
log_fail() { echo -e "  ${RED}✗${NC} $1"; TESTS_FAILED=$((TESTS_FAILED + 1)); }

echo "═══════════════════════════════════════════════════════════════"
echo "  pre-commit: deleted src/ path must not excuse a plugins/ edit"
echo "═══════════════════════════════════════════════════════════════"

mkdir -p "$fixture/bin/git-hooks" \
    "$fixture/src/skills/skill-a" "$fixture/plugins/ork/skills/skill-a"
cp "$ROOT/bin/git-hooks/pre-commit" "$fixture/bin/git-hooks/pre-commit"
cp "$ROOT/bin/git-hooks/plugins-src-guard.sh" "$fixture/bin/git-hooks/plugins-src-guard.sh"
chmod +x "$fixture/bin/git-hooks/pre-commit" "$fixture/bin/git-hooks/plugins-src-guard.sh"

cd "$fixture"
git init -q
git config user.email fixture@example.invalid
git config user.name Fixture
git config commit.gpgsign false
printf 'src\n' > src/skills/skill-a/SKILL.md
printf 'plugins\n' > plugins/ork/skills/skill-a/SKILL.md
git add .
git commit -qm base
git update-ref refs/remotes/origin/main HEAD

run_hook() {
  set +e
  # ORK_DIST_COMMIT=1 skips the release-owned bundle check: the fixture has no
  # release-dist-paths.sh helper, and this test targets the section-10 guard.
  ORK_DIST_COMMIT=1 "$fixture/bin/git-hooks/pre-commit" > "$fixture/hook.out" 2>&1
  HOOK_STATUS=$?
  set -e
}

# 1. Control: src/ counterpart modified earlier on the branch still excuses a
#    staged regen of its plugins/ copy (#4661 exemption stays).
printf 'src v2\n' > src/skills/skill-a/SKILL.md
git add src/skills/skill-a/SKILL.md
git commit -qm 'edit src skill'
printf 'plugins v2\n' > plugins/ork/skills/skill-a/SKILL.md
git add plugins/ork/skills/skill-a/SKILL.md
run_hook
if [[ "$HOOK_STATUS" -eq 0 ]] && grep -Fq 'Pre-commit validation passed' "$fixture/hook.out"; then
    log_pass "src/ file edited earlier on branch still excuses the plugins/ edit"
else
    log_fail "modified-src control: status=$HOOK_STATUS, output: $(cat "$fixture/hook.out")"
fi

# 2. The bug: src/ counterpart DELETED earlier on the branch must NOT excuse a
#    staged plugins/ edit. Before --diff-filter=d the branch file list still
#    named the deleted path and this printed OK.
git commit -qm 'regen plugins copy'
git rm -q src/skills/skill-a/SKILL.md
git commit -qm 'delete src skill'
printf 'plugins v3\n' > plugins/ork/skills/skill-a/SKILL.md
git add plugins/ork/skills/skill-a/SKILL.md
run_hook
if [[ "$HOOK_STATUS" -eq 1 ]] \
    && grep -Fq 'Generated output staged without its src/ counterpart' "$fixture/hook.out" \
    && grep -Fq 'plugins/ork/skills/skill-a/SKILL.md' "$fixture/hook.out"; then
    log_pass "deleted src/ file no longer excuses the plugins/ edit"
else
    log_fail "deleted-src case: status=$HOOK_STATUS, output: $(cat "$fixture/hook.out")"
fi

echo ""
echo "Passed: $TESTS_PASSED  Failed: $TESTS_FAILED"
[[ $TESTS_FAILED -gt 0 ]] && exit 1
exit 0
